import (
	"net/http"
	"testing"
)

// An unknown time zone must be rejected when the prefs are saved, not
// stored and then crash the digest later.
func TestPrefsRejectsUnknownZone(t *testing.T) {
	c := newClient(t)
	if code := c.do("tok-ana", http.MethodPut, "/v1/me/prefs", `{"tz":"Europe/Lisboa"}`, nil); code != http.StatusBadRequest {
		t.Fatalf("prefs with unknown zone: status %d, want 400", code)
	}
	if code := c.do("tok-ana", http.MethodGet, "/v1/me/digest?days=14", "", nil); code != http.StatusOK {
		t.Errorf("digest: status %d, want 200", code)
	}
}
"}

